import React, { useState, useEffect } from 'react';
import axios from 'axios';

export default function TeacherQuiz({ userName, subject, qualifications }) {
  const [quizzes, setQuizzes] = useState([]);
  const [selectedQuizId, setSelectedQuizId] = useState('');
  const [quizTitle, setQuizTitle] = useState('');
  const [quizType, setQuizType] = useState('Lesson Quiz'); // Lesson Quiz OR Term Exam
  
  // Active Tab: MCQ, Short Answer, Fill in the Blank (As in image_cf84c8.jpg)
  const [activeQuestionType, setActiveQuestionType] = useState('MCQ');
  const [questions, setQuestions] = useState([]);

  // Form Field States
  const [qText, setQText] = useState('');
  const [qMarks, setQMarks] = useState(2);
  const [optA, setOptA] = useState('');
  const [optB, setOptB] = useState('');
  const [optC, setOptC] = useState('');
  const [optD, setOptD] = useState('');
  const [correctOpt, setCorrectOpt] = useState('A');

  const fullSubject = subject || 'Grade 9 - IT';
  const subjectParts = fullSubject.split(' - ');
  const teachingGrade = subjectParts.length > 1 ? subjectParts[0] : 'Grade 9';
  const teachingSubject = subjectParts.length > 1 ? subjectParts[1] : fullSubject;

  // ඩේටාබේස් එකෙන් ක්විස් පේපර්ස් ලිස්ට් එක ගැනීම
  const fetchQuizzes = () => {
    axios.get('http://localhost:8081/api/quizzes')
      .then(res => setQuizzes(res.data))
      .catch(err => console.log(err));
  };

  // තෝරාගත් පේපර් එකට අදාළ ප්‍රශ්න විතරක් ඩේටාබේස් එකෙන් ලයිව් කියවීම
  const fetchQuestions = (quizId) => {
    if (!quizId) return;
    axios.get(`http://localhost:8081/api/questions/${quizId}`)
      .then(res => setQuestions(res.data))
      .catch(err => console.log(err));
  };

  useEffect(() => { 
    fetchQuizzes(); 
  }, []);
  
  useEffect(() => {
    if (selectedQuizId) fetchQuestions(selectedQuizId);
    else setQuestions([]);
  }, [selectedQuizId]);

  // පියවර 1: අලුත් Quiz Paper එකක් සෑදීම
  const handleCreateQuiz = (e) => {
    e.preventDefault();
    const fullTitle = `[${quizType}] ${quizTitle}`;
    const payload = { title: fullTitle, grade: teachingGrade, subject: teachingSubject, teacher_name: userName };
    
    axios.post('http://localhost:8081/api/add-quiz', payload).then(res => {
      if (res.data.status === "Success") {
        alert("✅ New Quiz Paper Created!");
        setQuizTitle(''); 
        fetchQuizzes();
      }
    });
  };

  // 🟢 පියවර 2: + Add Question ඔබපු ගමන් කෙලින්ම Database එකට සේව් වීම (මැඩම් හරි කියපු ක්‍රමය)
  const handleAddQuestion = (e) => {
    e.preventDefault();
    if (!selectedQuizId) { 
      alert("Please select a Quiz Paper from the dropdown first!"); 
      return; 
    }

    const payload = {
      quiz_id: selectedQuizId,
      question_text: qText,
      marks: qMarks,
      option_a: activeQuestionType === 'MCQ' ? optA : '',
      option_b: activeQuestionType === 'MCQ' ? optB : '',
      option_c: activeQuestionType === 'MCQ' ? optC : '',
      option_d: activeQuestionType === 'MCQ' ? optD : '',
      correct_option: activeQuestionType === 'MCQ' ? correctOpt : 'Written Answer'
    };

    axios.post('http://localhost:8081/api/add-question', payload).then(res => {
      if (res.data.status === "Success") {
        fetchQuestions(selectedQuizId); // Database එකෙන් ලයිව් අප්ඩේට් කර දකුණු පැත්තේ පෙන්වයි
        setQText(''); setOptA(''); setOptB(''); setOptC(''); setOptD(''); setCorrectOpt('A');
      }
    });
  };

  const handleDeleteQuestion = (id) => {
    if (window.confirm("Remove this question from database?")) {
      axios.delete(`http://localhost:8081/api/delete-question/${id}`).then(() => fetchQuestions(selectedQuizId));
    }
  };

  const totalMarks = questions.reduce((sum, q) => sum + parseInt(q.marks || 0), 0);

  return (
    <div style={{ animation: 'fadeIn 0.5s', fontFamily: 'sans-serif' }}>
      
      {/* 🟦 TOP HEADER CONTROL PANEL */}
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', backgroundColor: '#1e293b', padding: '15px 25px', borderRadius: '12px', color: 'white', marginBottom: '25px' }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: '15px' }}>
          <span style={{ fontWeight: 'bold', color: '#38bdf8' }}>HNDIT Question Builder</span>
          <form onSubmit={handleCreateQuiz} style={{ display: 'flex', gap: '10px' }}>
            <select value={quizType} onChange={e => setQuizType(e.target.value)} style={styles.topSelect}>
              <option value="Lesson Quiz">Lesson Quiz</option>
              <option value="Term Exam">Term Exam</option>
            </select>
            <input type="text" placeholder="Paper Title..." value={quizTitle} onChange={e => setQuizTitle(e.target.value)} required style={styles.topInput} />
            <button type="submit" style={styles.topBtn}>Create Paper</button>
          </form>
        </div>
        
        {selectedQuizId && (
          <div style={{ display: 'flex', gap: '15px', fontSize: '13px', color: '#94a3b8' }}>
            <span>⏱️ 30 min</span> | <span>📊 Total Marks: <span style={{color:'#f59e0b'}}>{totalMarks}</span></span> | <span>❓ {questions.length} Questions</span>
          </div>
        )}

        <div>
          <select value={selectedQuizId} onChange={e => setSelectedQuizId(e.target.value)} style={styles.dropdown}>
            <option value="">-- Select Active Paper --</option>
            {quizzes.filter(q => q.subject_name === teachingSubject).map(q => (
              <option key={q.id} value={q.id}>{q.title}</option>
            ))}
          </select>
        </div>
      </div>

      {/* 🟩 MAIN GRID LAYOUT (Left Form | Right Live List matching image_cf84c8.jpg) */}
      <div style={{ display: 'grid', gridTemplateColumns: '1fr 1.2fr', gap: '30px', alignItems: 'start' }}>
        
        {/* LEFT COMPONENT: ADD NEW QUESTION */}
        <div style={{ backgroundColor: 'white', padding: '30px', borderRadius: '12px', boxShadow: '0 4px 15px rgba(0,0,0,0.03)', border: '1px solid #e2e8f0' }}>
          <h3 style={{ margin: '0 0 20px 0', fontSize: '18px', color: '#1e293b' }}>Add New Question</h3>
          
          {/* Question Type Tabs (MCQ, Short Answer, Fill in the Blank) */}
          <div style={{ display: 'flex', gap: '10px', marginBottom: '20px' }}>
            <button type="button" onClick={() => setActiveQuestionType('MCQ')} style={{...styles.tabBtn, backgroundColor: activeQuestionType === 'MCQ' ? '#2563eb' : '#f1f5f9', color: activeQuestionType === 'MCQ' ? 'white' : '#475569'}}>🔷 MCQ</button>
            <button type="button" onClick={() => setActiveQuestionType('ShortAnswer')} style={{...styles.tabBtn, backgroundColor: activeQuestionType === 'ShortAnswer' ? '#2563eb' : '#f1f5f9', color: activeQuestionType === 'ShortAnswer' ? 'white' : '#475569'}}>📝 Short Answer</button>
            <button type="button" onClick={() => setActiveQuestionType('Blank')} style={{...styles.tabBtn, backgroundColor: activeQuestionType === 'Blank' ? '#2563eb' : '#f1f5f9', color: activeQuestionType === 'Blank' ? 'white' : '#475569'}}>✏️ Fill in Blank</button>
          </div>

          <form onSubmit={handleAddQuestion} style={{ display: 'flex', flexDirection: 'column', gap: '15px' }}>
            <div>
              <label style={styles.label}>Question *</label>
              <textarea placeholder="Enter your question here..." value={qText} onChange={e => setQText(e.target.value)} required style={styles.textarea} />
            </div>
            
            <div style={{ width: '120px' }}>
              <label style={styles.label}>Marks *</label>
              <input type="number" value={qMarks} onChange={e => setQMarks(e.target.value)} min="1" required style={styles.formInput} />
            </div>

            {/* MCQ Options UI Section */}
            {activeQuestionType === 'MCQ' && (
              <div>
                <label style={styles.label}>Options — select the correct answer check</label>
                <div style={{ display: 'flex', flexDirection: 'column', gap: '10px', marginTop: '8px' }}>
                  <div style={styles.optRow}><input type="radio" name="correct" checked={correctOpt === 'A'} onChange={() => setCorrectOpt('A')} /><input type="text" placeholder="Option A" value={optA} onChange={e => setOptA(e.target.value)} required style={styles.formInput} /></div>
                  <div style={styles.optRow}><input type="radio" name="correct" checked={correctOpt === 'B'} onChange={() => setCorrectOpt('B')} /><input type="radio" name="correct" checked={correctOpt === 'B'} onChange={() => setCorrectOpt('B')} /><input type="text" placeholder="Option B" value={optB} onChange={e => setOptB(e.target.value)} required style={styles.formInput} /></div>
                  <div style={styles.optRow}><input type="radio" name="correct" checked={correctOpt === 'C'} onChange={() => setCorrectOpt('C')} /><input type="text" placeholder="Option C" value={optC} onChange={e => setOptC(e.target.value)} required style={styles.formInput} /></div>
                  <div style={styles.optRow}><input type="radio" name="correct" checked={correctOpt === 'D'} onChange={() => setCorrectOpt('D')} /><input type="text" placeholder="Option D" value={optD} onChange={e => setOptD(e.target.value)} required style={styles.formInput} /></div>
                </div>
              </div>
            )}

            <button type="submit" style={styles.addQBtn}>+ Add Question</button>
          </form>
        </div>

        {/* RIGHT COMPONENT: LIVE LIST COMING FROM DATABASE */}
        <div style={{ display: 'flex', flexDirection: 'column', gap: '20px' }}>
          <h3 style={{ margin: 0, fontSize: '18px', color: '#1e293b' }}>Questions Saved Live ({questions.length})</h3>
          
          {questions.map((q, idx) => (
            <div key={q.id} style={{ backgroundColor: 'white', padding: '20px', borderRadius: '12px', border: '1px solid #cbd5e1', boxShadow: '0 2px 8px rgba(0,0,0,0.02)' }}>
              <div style={{ display: 'flex', justifyContent: 'space-between', fontSize: '12px', fontWeight: 'bold', marginBottom: '10px' }}>
                <span style={{ color: '#2563eb' }}>Q{idx + 1} ({q.marks} marks)</span>
                <button onClick={() => handleDeleteQuestion(q.id)} style={styles.delBtn}>🗑️ Delete</button>
              </div>
              <h4 style={{ margin: '0 0 12px 0', color: '#1e293b' }}>{q.question_text}</h4>
              
              {q.correct_option !== 'Written Answer' && (
                <div style={{ display: 'flex', flexDirection: 'column', gap: '6px', fontSize: '13px' }}>
                  <div style={{ color: q.correct_option === 'A' ? '#16a34a' : '#475569', fontWeight: q.correct_option === 'A' ? 'bold' : 'normal' }}>⭕ {q.option_a} {q.correct_option === 'A' && '✓ (Correct)'}</div>
                  <div style={{ color: q.correct_option === 'B' ? '#16a34a' : '#475569', fontWeight: q.correct_option === 'B' ? 'bold' : 'normal' }}>⭕ {q.option_b} {q.correct_option === 'B' && '✓ (Correct)'}</div>
                  <div style={{ color: q.correct_option === 'C' ? '#16a34a' : '#475569', fontWeight: q.correct_option === 'C' ? 'bold' : 'normal' }}>⭕ {q.option_c} {q.correct_option === 'C' && '✓ (Correct)'}</div>
                  <div style={{ color: q.correct_option === 'D' ? '#16a34a' : '#475569', fontWeight: q.correct_option === 'D' ? 'bold' : 'normal' }}>⭕ {q.option_d} {q.correct_option === 'D' && '✓ (Correct)'}</div>
                </div>
              )}
            </div>
          ))}

          {questions.length === 0 && (
            <div style={{ backgroundColor: 'white', padding: '40px', borderRadius: '12px', textAlign: 'center', color: '#94a3b8', border: '1px solid #cbd5e1' }}>
              Select a quiz paper from dropdown to view saved questions live from the database.
            </div>
          )}
        </div>

      </div>
    </div>
  );
}

const styles = {
  topSelect: { padding: '6px', borderRadius: '6px', border: '1px solid #475569', fontSize: '13px' },
  topInput: { padding: '6px 12px', borderRadius: '6px', border: '1px solid #475569', fontSize: '13px', outline: 'none' },
  topBtn: { padding: '6px 15px', backgroundColor: '#15803d', color: 'white', border: 'none', borderRadius: '6px', cursor: 'pointer', fontWeight: 'bold', fontSize: '13px' },
  dropdown: { padding: '8px 15px', borderRadius: '6px', backgroundColor: 'white', color: '#1e293b', border: '1px solid #cbd5e1', fontWeight: 'bold', minWidth: '220px', outline: 'none' },
  tabBtn: { padding: '8px 15px', border: 'none', borderRadius: '6px', cursor: 'pointer', fontSize: '12px', fontWeight: 'bold' },
  label: { display: 'block', color: '#475569', fontSize: '12px', fontWeight: 'bold', marginBottom: '5px' },
  textarea: { width: '100%', padding: '12px', borderRadius: '8px', border: '1px solid #cbd5e1', backgroundColor: '#f8fafc', height: '80px', boxSizing: 'border-box', outline: 'none' },
  formInput: { width: '100%', padding: '10px 12px', borderRadius: '6px', border: '1px solid #cbd5e1', backgroundColor: '#f8fafc', outline: 'none', boxSizing: 'border-box', fontSize: '13px' },
  optRow: { display: 'flex', alignItems: 'center', gap: '10px', width: '100%' },
  addQBtn: { padding: '12px', backgroundColor: '#2563eb', color: 'white', border: 'none', borderRadius: '8px', fontWeight: 'bold', cursor: 'pointer', marginTop: '10px', fontSize: '14px' },
  delBtn: { color: '#dc2626', backgroundColor: '#fee2e2', padding: '4px 10px', borderRadius: '4px', border: 'none', cursor: 'pointer', fontSize: '12px', fontWeight: 'bold' }
};
